package com.workpro.agent;
import com.workpro.dialogue.*; import com.workpro.domain.Contracts.*; import com.workpro.rag.RetrievalContracts.*; import java.time.Duration; import java.util.*; import static com.workpro.agent.AgentContracts.*; import org.springframework.stereotype.Service;
@Service class ResearchAgentAdapter implements Agent { private final ResearchAgent delegate; ResearchAgentAdapter(ResearchAgent d){delegate=d;} public AgentDefinition definition(){return new AgentDefinition("research","1",Set.of("retrieval"),Set.of("rag.search"),Duration.ofSeconds(30),1);} public AgentResult execute(AgentInput i,AgentContext c){var p=delegate.research(new RetrievalRequest(c.query(),null,null,8,Map.of()));c.put("evidence",p.results().stream().map(RetrievalResult::content_preview).toList());c.put("evidenceRefs",p.evidenceRefs());return new Success(new AgentOutput("success","检索完成",Map.of("count",p.results().size())));}}
@Service class WriterAgentAdapter implements Agent { private final WriterAgent delegate; WriterAgentAdapter(WriterAgent d){delegate=d;} public AgentDefinition definition(){return new AgentDefinition("writer","1",Set.of("generation"),Set.of("llm.complete"),Duration.ofSeconds(60),1);} public AgentResult execute(AgentInput i,AgentContext c){var a=delegate.write(c.query(),c.get("evidence"));c.put("answer",a);return new Success(new AgentOutput("success",a,Map.of()));}}
@Service class ReviewAgentAdapter implements Agent { private final ReviewAgent delegate; ReviewAgentAdapter(ReviewAgent d){delegate=d;} public AgentDefinition definition(){return new AgentDefinition("review","1",Set.of("validation"),Set.of(),Duration.ofSeconds(15),0);} public AgentResult execute(AgentInput i,AgentContext c){var r=delegate.review(c.get("answer"));return "success".equals(r.status())?new Success(new AgentOutput("success",r.message(),Map.of())):new Blocked(r.message());}}
